// Stamps the database named by DIRECT_DATABASE_URL as one copy's: `node scripts/claim-copy.ts <test|live>`.
// The deploy command runs it after the migrations and before the Worker goes out, so code is never deployed to a
// database that belongs to the other copy.
//
// It uses `pg`, not Prisma's client, because the client is generated by the build, and this must also run where
// nothing has been generated yet.
import pg from "pg";
import { claimCopy, readCopy } from "../src/lib/server/copy.ts";

async function main(): Promise<void> {
  const copy = readCopy({ RUKEN_COPY: process.argv[2] });
  const address = process.env.DIRECT_DATABASE_URL;
  if (address === undefined || address === "") throw new Error("DIRECT_DATABASE_URL is not set.");
  const pool = new pg.Pool({ connectionString: address, max: 1 });
  try {
    await claimCopy(
      (sql, values) => pool.query<Record<string, unknown>>(sql, [...values]).then((result) => result.rows),
      copy,
    );
  } finally {
    await pool.end();
  }
  console.log(`This database is the ${copy} copy's.`);
}

main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
});
